"""Library API reference, generated by runtime introspection of ``oscal``.

The index is built once (lazily) from ``oscal.gendocs.collect_api`` against the
*installed* package, so it always reflects the version in use — new getters/setters
added as the library matures appear automatically with no server changes.

Exposes:
* resource ``oscal-lib://api`` — compact index (modules → classes → members, with
  signatures), suitable for browsing;
* resource ``oscal-lib://api/{fqname}`` — full detail (signature + verbatim docstring)
  for one fully-qualified symbol;
* tool ``search_library_api(query, limit)`` — ranked search across names, signatures
  and docstrings for targeted lookups.
"""

from __future__ import annotations

import os
import threading
from typing import List, Optional

from fastmcp.exceptions import ToolError

from ..state import DocumentStore

_lock = threading.Lock()
_symbols: Optional[List[dict]] = None  # flat list of symbol records
_tree: Optional[dict] = None  # nested module/class/member view
_meta: Optional[dict] = None  # project/version metadata


def _build_index() -> None:
    """Introspect the installed ``oscal`` package into flat + nested indexes (once)."""
    global _symbols, _tree, _meta
    with _lock:
        if _symbols is not None:
            return
        import oscal as _oscal
        from oscal import gendocs

        data = gendocs.collect_api(os.path.dirname(_oscal.__file__))
        _meta = {
            "project_name": data.get("project_name"),
            "package_name": data.get("package_name"),
            "version": data.get("version"),
            "generated": data.get("generated"),
        }

        symbols: List[dict] = []
        tree_modules = []

        def _record(fqname, kind, signature, doc, module, cls):
            symbols.append(
                {
                    "fqname": fqname,
                    "kind": kind,
                    "signature": signature or "",
                    "doc": doc or "",
                    "module": module,
                    "class": cls,
                }
            )

        for mod in data.get("modules", []):
            mname = mod.get("name")
            mod_view = {"name": mname, "doc": _first_line(mod.get("doc")), "classes": [], "functions": []}

            for fn in mod.get("functions", []):
                fq = f"{mname}.{fn.get('name')}"
                _record(fq, fn.get("kind", "function"), fn.get("signature"), fn.get("doc"), mname, None)
                mod_view["functions"].append({"fqname": fq, "signature": fn.get("signature", "")})

            for cls in mod.get("classes", []):
                cname = cls.get("name")
                cls_fq = f"{mname}.{cname}"
                _record(cls_fq, "class", None, cls.get("doc"), mname, cname)
                cls_view = {"fqname": cls_fq, "doc": _first_line(cls.get("doc")), "members": []}
                for mem in cls.get("members", []):
                    fq = f"{cls_fq}.{mem.get('name')}"
                    _record(fq, mem.get("kind", "method"), mem.get("signature"), mem.get("doc"), mname, cname)
                    cls_view["members"].append(
                        {"fqname": fq, "kind": mem.get("kind", "method"), "signature": mem.get("signature", "")}
                    )
                mod_view["classes"].append(cls_view)

            tree_modules.append(mod_view)

        _symbols = symbols
        _tree = {"meta": _meta, "modules": tree_modules}


def _first_line(doc: Optional[str]) -> str:
    if not doc:
        return ""
    return doc.strip().splitlines()[0].strip() if doc.strip() else ""


def _score(record: dict, terms: List[str]) -> int:
    """Rank a symbol against query terms: name > signature > docstring."""
    name = record["fqname"].lower()
    leaf = record["fqname"].rsplit(".", 1)[-1].lower()
    sig = record["signature"].lower()
    doc = record["doc"].lower()
    score = 0
    for t in terms:
        if leaf == t:
            score += 100
        if t in leaf:
            score += 40
        elif t in name:
            score += 20
        if t in sig:
            score += 8
        if t in doc:
            score += 3
    return score


def register(mcp, store: DocumentStore) -> None:
    @mcp.resource("oscal-lib://api")
    def api_index() -> dict:
        """Compact index of the ``oscal`` library API (modules → classes → members).

        Each entry carries its fully-qualified name and signature. Use
        ``oscal-lib://api/{fqname}`` or ``search_library_api`` to retrieve full
        docstrings.
        """
        _build_index()
        return _tree  # type: ignore[return-value]

    @mcp.resource("oscal-lib://api/{fqname}")
    def api_symbol(fqname: str) -> dict:
        """Full detail for one library symbol: kind, signature, and verbatim docstring.

        ``fqname`` is a fully-qualified name such as
        ``oscal.oscal_controls.Catalog.create_control``.
        """
        _build_index()
        for rec in _symbols:  # type: ignore[union-attr]
            if rec["fqname"] == fqname:
                return rec
        # Also allow matching by leaf name when unambiguous.
        matches = [r for r in _symbols if r["fqname"].rsplit(".", 1)[-1] == fqname]  # type: ignore[union-attr]
        if len(matches) == 1:
            return matches[0]
        raise ToolError(
            f"No symbol {fqname!r} in the oscal API index"
            + (f" ({len(matches)} leaf-name matches; use the full name)" if matches else "")
        )

    @mcp.tool
    def search_library_api(query: str, limit: int = 20) -> dict:
        """Search the ``oscal`` library API for symbols matching a query.

        Ranks classes, methods and functions by how well the query matches their name
        (highest), signature, then docstring. Use this to discover how to call the
        library from Python (e.g. ``search_library_api("resolve profile")`` or
        ``search_library_api("validate")``). Returns the top ``limit`` results, each
        with fully-qualified name, kind, signature, and the first docstring line.
        """
        if not query or not query.strip():
            raise ToolError("query must be a non-empty string.")
        _build_index()
        terms = [t for t in query.lower().split() if t]
        scored = []
        for rec in _symbols:  # type: ignore[union-attr]
            s = _score(rec, terms)
            if s > 0:
                scored.append((s, rec))
        scored.sort(key=lambda sr: sr[0], reverse=True)
        results = [
            {
                "fqname": rec["fqname"],
                "kind": rec["kind"],
                "signature": rec["signature"],
                "summary": _first_line(rec["doc"]),
                "score": s,
            }
            for s, rec in scored[: max(1, limit)]
        ]
        return {"query": query, "count": len(results), "results": results}
